200→	full := cellGroup{cell: euWestCell, jurisdiction: "eu", baseURL: "https://aws-eu-west-1.api.entire.io"}
201→	if tgt := full.cellTarget(); tgt == nil || tgt.BaseURL != full.baseURL || tgt.Jurisdiction != "eu" {
202→		t.Fatalf("full target = %+v", tgt)
203→	}
204→	jur := cellGroup{jurisdiction: "eu"}
205→	if tgt := jur.cellTarget(); tgt == nil || tgt.BaseURL != "" || tgt.Jurisdiction != "eu" {
206→		t.Fatalf("jurisdiction-only target = %+v", tgt)
207→	}
208→	if tgt := (cellGroup{}).cellTarget(); tgt != nil {
209→		t.Fatalf("empty group target = %+v, want nil (home routing)", tgt)
210→	}
211→	if got := full.label(); got != euWestCell {
212→		t.Fatalf("label = %q", got)
213→	}
214→	if got := jur.label(); got != "eu" {
215→		t.Fatalf("label = %q", got)
216→	}
217→	if got := (cellGroup{}).label(); got != "home" {
218→		t.Fatalf("label = %q, want home", got)
219→	}
220→}
