244→func withFakeCellClientBuilder(t *testing.T, f *fakeCellClientBuilder) {
245→	t.Helper()
246→	prev := newCellClientBuilder
247→	newCellClientBuilder = func(context.Context, bool) (cellClientBuilder, error) { return f, nil }
248→	t.Cleanup(func() { newCellClientBuilder = prev })
249→}
