251→func TestFanOutCells_PartialFailureIsPerCell(t *testing.T) {
252→	// Not parallel: swaps the package-level newCellClientBuilder seam.
253→	withFakeCellClientBuilder(t, &fakeCellClientBuilder{})
254→	cells := []cellGroup{
255→		{cell: euWestCell, jurisdiction: "eu", baseURL: "https://eu.api.example", repoIDs: []string{"01A"}},
256→		{cell: "aws-us-east-2", jurisdiction: "us", baseURL: "https://us.api.example", repoIDs: []string{"01B"}},
257→	}
258→	boom := errors.New("cell down")
259→	results, err := fanOutCells(context.Background(), false, time.Second, cells,
260→		func(ctx context.Context, g cellGroup, _ *api.Client) (string, error) {
261→			if _, ok := ctx.Deadline(); !ok {
262→				t.Error("per-cell ctx has no deadline")
263→			}
264→			if g.cell == euWestCell {
265→				return "", boom
266→			}
267→			return "hits:" + strings.Join(g.repoIDs, ","), nil
268→		})
269→	if err != nil {
270→		t.Fatalf("fanOutCells: %v", err)
271→	}
272→	if len(results) != 2 {
273→		t.Fatalf("results = %d, want 2", len(results))
274→	}
275→	// Input order preserved; the eu failure is isolated in its slot.
276→	if !errors.Is(results[0].err, boom) || results[0].group.cell != euWestCell {
277→		t.Fatalf("results[0] = %+v, want eu failure", results[0])
278→	}
279→	if results[1].err != nil || results[1].value != "hits:01B" {
280→		t.Fatalf("results[1] = %+v, want us success", results[1])
281→	}
282→}
