284→func TestFanOutCells_SingleCellRunsSerially(t *testing.T) {
285→	// Not parallel: swaps the package-level newCellClientBuilder seam.
286→	builder := &fakeCellClientBuilder{}
287→	withFakeCellClientBuilder(t, builder)
