  1→package review
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"sort"
 11→	"strings"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 15→	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
 16→	"github.com/entireio/cli/cmd/entire/cli/settings"
 17→)
 18→
 19→const DefaultProfileName = "general"
 20→
 21→// Review output destinations. ReviewOutputLocal prints the verdict and writes
 22→// the local review manifest; ReviewOutputTrail additionally posts the verdict
 23→// to the branch's trail as a finding (`entire trail finding`).
 24→const (
 25→	ReviewOutputLocal = "local"
 26→	ReviewOutputTrail = "trail"
 27→)
 28→
 29→// profileOutput resolves the configured output destination, defaulting to
 30→// local. Unknown values fall back to local.
 31→func profileOutput(profile settings.ReviewProfileConfig) string {
 32→	if strings.EqualFold(strings.TrimSpace(profile.Output), ReviewOutputTrail) {
 33→		return ReviewOutputTrail
 34→	}
 35→	return ReviewOutputLocal
 36→}
 37→
 38→// normalizeReviewOutput validates a user-supplied output value, returning the
 39→// canonical form. Empty is allowed (means local).
 40→func normalizeReviewOutput(raw string) (string, error) {
 41→	switch strings.ToLower(strings.TrimSpace(raw)) {
 42→	case "", ReviewOutputLocal:
 43→		return ReviewOutputLocal, nil
 44→	case ReviewOutputTrail:
 45→		return ReviewOutputTrail, nil
 46→	default:
 47→		return "", fmt.Errorf("invalid output %q; valid values are %s, %s", raw, ReviewOutputLocal, ReviewOutputTrail)
 48→	}
 49→}
 50→
 51→const (
 52→	defaultGeneralTask       = "Review this change for correctness, regressions, API design, missing tests, maintainability, and user-facing behavior changes. Return only real, actionable defects with concrete evidence and an exact code pointer. No praise, summaries, speculation, style preferences, or nice-to-have refactors."
 53→	defaultSecurityTask      = "Review this change for security vulnerabilities: authentication and authorization bugs, injection risks, secrets exposure, unsafe dependency or deserialization behavior, privilege-boundary mistakes, insecure defaults, and data leakage. Return only exploitable or clearly risky defects with concrete evidence and an exact code pointer. No praise, summaries, speculation, or hardening wishlists."
 54→	defaultAccessibilityTask = "Review this change for accessibility regressions: keyboard navigation, focus management, semantic markup, labels, ARIA correctness, color contrast, reduced-motion behavior, screen-reader behavior, and inclusive error states. Return only concrete user-impacting defects with an exact code pointer. No praise, summaries, speculation, or generic best-practice advice."
 55→)
 56→
 57→// profileTask returns the configured task, or a built-in task for conventional
 58→// profile names when the config leaves task empty.
 59→func profileTask(name string, cfg settings.ReviewProfileConfig) string {
 60→	if strings.TrimSpace(cfg.Task) != "" {
 61→		return strings.TrimSpace(cfg.Task)
 62→	}
 63→	switch strings.ToLower(name) {
 64→	case "", DefaultProfileName:
 65→		return defaultGeneralTask
 66→	case "security":
 67→		return defaultSecurityTask
 68→	case "accessibility", "a11y":
 69→		return defaultAccessibilityTask
 70→	default:
 71→		return defaultGeneralTask
 72→	}
 73→}
 74→
 75→// selectReviewProfile resolves the profile to run. When no review_profiles are
 76→// configured, a legacy top-level review map is exposed as the general profile so
 77→// upgrades keep honoring existing review setups until the user saves profiles.
 78→func selectReviewProfile(s *settings.EntireSettings, override string) (string, settings.ReviewProfileConfig, error) {
 79→	applyLegacyReviewProfileFallback(s)
 80→	if s == nil || len(s.ReviewProfiles) == 0 {
 81→		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; run `entire review --configure` or add review_profiles to Entire preferences")
 82→	}
 83→	profiles := nonZeroProfiles(s.ReviewProfiles)
 84→	if len(profiles) == 0 {
 85→		return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; every profile is empty")
 86→	}
 87→
 88→	name := strings.TrimSpace(override)
 89→	if name == "" {
 90→		name = strings.TrimSpace(s.ReviewDefaultProfile)
 91→	}
 92→	if name == "" {
 93→		if _, ok := profiles[DefaultProfileName]; ok {
 94→			name = DefaultProfileName
 95→		} else if len(profiles) == 1 {
 96→			for only := range profiles {
 97→				name = only
 98→			}
 99→		} else {
100→			return "", settings.ReviewProfileConfig{}, fmt.Errorf(
101→				"multiple review profiles configured (%s); pass a profile name or set review_default_profile",
102→				strings.Join(sortedMapKeys(profiles), ", "))
103→		}
104→	}
105→
106→	cfg, ok := profiles[name]
107→	if !ok {
108→		return "", settings.ReviewProfileConfig{}, fmt.Errorf(
109→			"review profile %q is not configured; configured profiles: %s",
110→			name, strings.Join(sortedMapKeys(profiles), ", "))
111→	}
112→	if len(nonZeroAgentConfigs(cfg.Agents)) == 0 {
113→		return "", settings.ReviewProfileConfig{}, fmt.Errorf("review profile %q has no configured agents", name)
114→	}
115→	return name, cfg, nil
116→}
117→
118→func applyLegacyReviewProfileFallback(s *settings.EntireSettings) {
119→	if s == nil || len(nonZeroProfiles(s.ReviewProfiles)) > 0 {
120→		return
121→	}
122→	legacyAgents := nonZeroAgentConfigs(s.Review) //nolint:staticcheck // intentional compatibility fallback for deprecated review config
123→	if len(legacyAgents) == 0 {
124→		return
125→	}
126→	s.ReviewProfiles = map[string]settings.ReviewProfileConfig{
127→		DefaultProfileName: {
128→			Agents: legacyAgents,
129→		},
130→	}
131→	if strings.TrimSpace(s.ReviewDefaultProfile) == "" {
132→		s.ReviewDefaultProfile = DefaultProfileName
133→	}
134→}
135→
136→func nonZeroProfiles(in map[string]settings.ReviewProfileConfig) map[string]settings.ReviewProfileConfig {
137→	return nonZeroNamed(in)
138→}
139→
140→func nonZeroAgentConfigs(in map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
141→	return nonZeroNamed(in)
142→}
143→
144→// nonZeroNamed drops entries with blank names or zero-valued configs.
145→func nonZeroNamed[T interface{ IsZero() bool }](in map[string]T) map[string]T {
146→	out := make(map[string]T, len(in))
147→	for name, cfg := range in {
148→		name = strings.TrimSpace(name)
149→		if name == "" || cfg.IsZero() {
150→			continue
151→		}
152→		out[name] = cfg
153→	}
154→	return out
155→}
156→
157→func reviewAgentName(workerName string, cfg settings.ReviewConfig) string {
158→	if strings.TrimSpace(cfg.Agent) != "" {
159→		return strings.TrimSpace(cfg.Agent)
160→	}
161→	return strings.TrimSpace(workerName)
162→}
163→
164→func reviewWorkerLabel(workerName string, cfg settings.ReviewConfig) string {
165→	agentName := reviewAgentName(workerName, cfg)
166→	parts := []string{workerName}
167→	var details []string
168→	if agentName != "" && agentName != workerName {
169→		details = append(details, agentName)
170→	}
171→	if strings.TrimSpace(cfg.Model) != "" {
172→		details = append(details, "model "+strings.TrimSpace(cfg.Model))
173→	}
174→	if len(details) > 0 {
175→		parts = append(parts, "  ("+strings.Join(details, ", ")+")")
176→	}
177→	return strings.Join(parts, "")
178→}
179→
180→// judgeSpec is the resolved consolidating judge: the agent that renders the
181→// final verdict plus its optional model.
182→type judgeSpec struct {
183→	agent string
184→	model string
185→}
186→
187→// profileJudge resolves the configured consolidating judge. ok is false when
188→// the profile has no judge set (a single-reviewer profile, or one left to the
189→// runtime default); callers fall back to resolveJudge for the default pick.
190→func profileJudge(profile settings.ReviewProfileConfig) (judgeSpec, bool) {
191→	if profile.Judge == nil {
192→		return judgeSpec{}, false
193→	}
194→	name := strings.TrimSpace(profile.Judge.Agent)
195→	if name == "" {
196→		return judgeSpec{}, false
197→	}
198→	model := strings.TrimSpace(profile.Judge.Model)
199→	// If the judge names one of the profile's worker ids (possibly an alias such
200→	// as "claude-opus" for {agent: claude-code, model: opus}), resolve it to the
201→	// underlying agent the synthesis provider can actually launch, inheriting the
202→	// worker's model when the judge didn't specify one. Otherwise the judge is a
203→	// standalone agent name and is used as-is.
204→	if cfg, ok := profile.Agents[name]; ok && !cfg.IsZero() {
205→		if model == "" {
206→			model = strings.TrimSpace(cfg.Model)
207→		}
208→		name = reviewAgentName(name, cfg)
209→	}
210→	return judgeSpec{agent: name, model: model}, true
211→}
212→
213→// resolveJudge returns the judge to use for a fan-out run: the explicitly
214→// configured judge, or an auto-selected text-gen reviewer when none is set.
215→func resolveJudge(ctx context.Context, profile settings.ReviewProfileConfig) (judgeSpec, bool) {
216→	if j, ok := profileJudge(profile); ok {
217→		return j, true
218→	}
219→	return defaultJudge(ctx, profile.Agents)
220→}
