222→// judgeLabel renders a judge for UI output: "agent" or "agent · model".
223→func judgeLabel(j judgeSpec) string {
224→	if strings.TrimSpace(j.model) != "" {
225→		return labelForSimpleAgent(j.agent) + " · " + j.model
226→	}
227→	return labelForSimpleAgent(j.agent)
