230→func selectProfileWorker(profile settings.ReviewProfileConfig, selector string) (string, settings.ReviewConfig, error) {
231→	selector = strings.TrimSpace(selector)
232→	if selector == "" {
233→		return "", settings.ReviewConfig{}, errors.New("empty review reviewer selector")
234→	}
235→	if cfg, ok := profile.Agents[selector]; ok && !cfg.IsZero() {
236→		return selector, cfg, nil
237→	}
238→	var matches []string
239→	for workerName, cfg := range profile.Agents {
240→		if cfg.IsZero() {
241→			continue
242→		}
243→		if reviewAgentName(workerName, cfg) == selector {
244→			matches = append(matches, workerName)
245→		}
246→	}
247→	sort.Strings(matches)
248→	switch len(matches) {
249→	case 1:
250→		return matches[0], profile.Agents[matches[0]], nil
251→	case 0:
252→		configured := sortedMapKeys(profile.Agents)
253→		if len(configured) == 0 {
254→			return "", settings.ReviewConfig{}, fmt.Errorf("review reviewer or agent %q is not configured", selector)
255→		}
256→		return "", settings.ReviewConfig{}, fmt.Errorf("review reviewer or agent %q is not configured; configured reviewers: %s", selector, strings.Join(configured, ", "))
257→	default:
258→		return "", settings.ReviewConfig{}, fmt.Errorf("agent %q has multiple review reviewers (%s); choose one by reviewer name", selector, strings.Join(matches, ", "))
259→	}
260→}
