262→func workerIDForAgentModel(agentName, model string, existing map[string]settings.ReviewConfig) string {
263→	base := strings.TrimSpace(agentName)
264→	if strings.TrimSpace(model) != "" {
265→		base += ":" + sanitizeWorkerIDPart(model)
266→	}
267→	if base == "" {
268→		base = "worker"
269→	}
270→	candidate := base
271→	for i := 2; ; i++ {
272→		if _, exists := existing[candidate]; !exists {
273→			return candidate
274→		}
275→		candidate = fmt.Sprintf("%s-%d", base, i)
276→	}
277→}
278→
279→func sanitizeWorkerIDPart(s string) string {
280→	s = strings.ToLower(strings.TrimSpace(s))
281→	var b strings.Builder
282→	lastDash := false
283→	for _, r := range s {
284→		keep := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
285→		if keep {
286→			b.WriteRune(r)
287→			lastDash = false
288→			continue
289→		}
290→		if !lastDash {
291→			b.WriteByte('-')
292→			lastDash = true
293→		}
294→	}
295→	out := strings.Trim(b.String(), "-")
296→	if out == "" {
297→		return "model"
298→	}
299→	return out
300→}
