302→func defaultReviewProfileForInstalledAgents(
303→	ctx context.Context,
304→	profileName string,
305→	installed []types.AgentName,
306→	reviewerFor func(string) reviewtypes.AgentReviewer,
307→) (settings.ReviewProfileConfig, error) {
308→	profileName = strings.TrimSpace(profileName)
309→	if profileName == "" {
310→		profileName = DefaultProfileName
311→	}
312→	installedNames := make([]string, 0, len(installed))
313→	for _, name := range installed {
314→		installedNames = append(installedNames, string(name))
315→	}
316→	sort.Strings(installedNames)
317→
318→	agents := make(map[string]settings.ReviewConfig, len(installedNames))
319→	for _, name := range installedNames {
320→		if reviewerFor != nil && reviewerFor(name) == nil {
321→			continue
322→		}
323→		cfg := defaultReviewAgentConfig(profileName, name)
324→		if cfg.IsZero() {
325→			continue
326→		}
327→		agents[name] = cfg
328→	}
329→	if len(agents) == 0 {
330→		return settings.ReviewProfileConfig{}, errors.New("no agents with review runner adapters and hooks installed; run `entire configure --agent claude-code`, `entire configure --agent codex`, `entire configure --agent gemini`, or `entire configure --agent pi`")
331→	}
332→	profile := settings.ReviewProfileConfig{
333→		Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
334→		Agents: agents,
335→	}
336→	if j, ok := defaultJudge(ctx, agents); ok {
337→		profile.Judge = &settings.ReviewConfig{Agent: j.agent, Model: j.model}
338→	}
339→	return profile, nil
340→}
