342→func defaultReviewAgentConfig(profileName, agentName string) settings.ReviewConfig {
343→	focus := defaultProfileFocus(profileName)
344→	switch agentName {
345→	case string(agent.AgentNameClaudeCode):
346→		if strings.EqualFold(profileName, "security") {
347→			return settings.ReviewConfig{Skills: []string{"/security-review"}}
348→		}
349→		return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
350→	case string(agent.AgentNameCodex):
351→		return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
352→	case string(agent.AgentNameGemini), string(agent.AgentNamePi):
353→		prompt := "Review the change according to the profile task."
354→		if focus != "" {
355→			prompt += " " + focus
356→		}
357→		return settings.ReviewConfig{Prompt: prompt}
358→	default:
359→		return settings.ReviewConfig{}
360→	}
361→}
