363→func defaultProfileFocus(profileName string) string {
364→	switch strings.ToLower(strings.TrimSpace(profileName)) {
365→	case "security":
366→		return "Focus specifically on security issues."
367→	case "accessibility", "a11y":
368→		return "Focus specifically on accessibility issues."
369→	default:
370→		return ""
371→	}
372→}
