374→// defaultJudge auto-selects a consolidating judge from the configured
375→// reviewers: it prefers claude-code, then codex, then gemini, then pi, and
376→// otherwise takes the first reviewer that can write a verdict (text generation).
377→// ok is false when no reviewer can.
378→func defaultJudge(ctx context.Context, configured map[string]settings.ReviewConfig) (judgeSpec, bool) {
379→	for _, preferred := range []string{string(agent.AgentNameClaudeCode), string(agent.AgentNameCodex), string(agent.AgentNameGemini), string(agent.AgentNamePi)} {
380→		for _, workerName := range sortedMapKeys(configured) {
381→			cfg := configured[workerName]
382→			if reviewAgentName(workerName, cfg) == preferred && agentSupportsTextGeneration(ctx, preferred) {
383→				return judgeSpec{agent: preferred, model: strings.TrimSpace(cfg.Model)}, true
384→			}
385→		}
386→	}
387→	for _, workerName := range sortedMapKeys(configured) {
388→		cfg := configured[workerName]
389→		if name := reviewAgentName(workerName, cfg); agentSupportsTextGeneration(ctx, name) {
390→			return judgeSpec{agent: name, model: strings.TrimSpace(cfg.Model)}, true
391→		}
392→	}
393→	return judgeSpec{}, false
394→}
395→
396→func sortedMapKeys[V any](in map[string]V) []string {
397→	names := make([]string, 0, len(in))
398→	for name := range in {
399→		names = append(names, name)
400→	}
401→	sort.Strings(names)
402→	return names
403→}
