405→func agentSupportsTextGeneration(_ context.Context, name string) bool {
406→	ag, err := agent.Get(types.AgentName(name))
407→	if err != nil {
408→		return false
409→	}
410→	_, ok := agent.AsTextGenerator(ag)
411→	return ok
412→}
