414→// reviewSettingsScope selects which settings file a review profile is written
415→// to. Both files are read and merged by settings.Load; the scope only decides
416→// where new profiles are persisted.
417→type reviewSettingsScope int
418→
419→const (
420→	// reviewScopeProject writes to .entire/settings.json (shared, committed).
421→	reviewScopeProject reviewSettingsScope = iota
422→	// reviewScopeLocal writes to .entire/settings.local.json (per-developer).
423→	reviewScopeLocal
424→)
425→
426→// file returns the settings filename this scope writes to.
427→func (s reviewSettingsScope) file() string {
428→	if s == reviewScopeLocal {
429→		return settings.EntireSettingsLocalFile
430→	}
431→	return settings.EntireSettingsFile
432→}
433→
434→// saveReviewProfile persists one profile into the chosen settings file via a
435→// raw read-modify-write so unrelated keys (and other profiles) are preserved.
436→func saveReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig, makeDefault bool, scope reviewSettingsScope) error {
437→	path, raw, err := loadReviewSettingsRaw(ctx, scope)
438→	if err != nil {
439→		return err
440→	}
441→	profiles, err := decodeRawReviewProfiles(raw)
442→	if err != nil {
443→		return err
444→	}
445→	hadProfiles := len(profiles) > 0
446→	profiles[profileName] = profile
447→	defaultName := decodeRawReviewDefault(raw)
448→	switch {
449→	case makeDefault:
450→		defaultName = profileName
451→	case strings.TrimSpace(defaultName) == "" && !hadProfiles:
452→		hasLower, err := lowerReviewDefaultOrProfiles(ctx, scope)
453→		if err != nil {
454→			return err
455→		}
456→		if !hasLower {
457→			defaultName = profileName
458→		}
459→	}
460→	return writeRawReviewProfiles(path, raw, profiles, defaultName)
461→}
462→
463→func lowerReviewDefaultOrProfiles(ctx context.Context, scope reviewSettingsScope) (bool, error) {
464→	if scope != reviewScopeLocal {
465→		return false, nil
466→	}
467→	_, raw, exists, err := settings.LoadProjectRaw(ctx)
468→	if err != nil {
469→		return false, fmt.Errorf("load project settings before local default check: %w", err)
470→	}
471→	if !exists || raw == nil {
472→		return false, nil
473→	}
474→	return rawHasReviewDefaultOrProfiles(raw)
475→}
476→
477→func rawHasReviewDefaultOrProfiles(raw map[string]json.RawMessage) (bool, error) {
478→	if strings.TrimSpace(decodeRawReviewDefault(raw)) != "" {
479→		return true, nil
480→	}
481→	profiles, err := decodeRawReviewProfiles(raw)
482→	if err != nil {
483→		return false, err
484→	}
485→	return len(profiles) > 0, nil
486→}
487→
488→// loadReviewSettingsRaw reads the raw JSON object for the chosen settings file.
489→func loadReviewSettingsRaw(ctx context.Context, scope reviewSettingsScope) (string, map[string]json.RawMessage, error) {
490→	var (
491→		path string
492→		raw  map[string]json.RawMessage
493→		err  error
494→	)
495→	if scope == reviewScopeLocal {
496→		path, raw, _, err = settings.LoadLocalRaw(ctx)
497→	} else {
498→		path, raw, _, err = settings.LoadProjectRaw(ctx)
499→	}
500→	if err != nil {
501→		return "", nil, fmt.Errorf("load %s before save: %w", scope.file(), err)
502→	}
503→	if raw == nil {
504→		raw = map[string]json.RawMessage{}
505→	}
506→	return path, raw, nil
507→}
508→
509→func decodeRawReviewProfiles(raw map[string]json.RawMessage) (map[string]settings.ReviewProfileConfig, error) {
510→	profiles := map[string]settings.ReviewProfileConfig{}
511→	if msg, ok := raw["review_profiles"]; ok && len(msg) > 0 {
512→		if err := json.Unmarshal(msg, &profiles); err != nil {
513→			return nil, fmt.Errorf("parse existing review_profiles: %w", err)
514→		}
515→		if profiles == nil {
516→			profiles = map[string]settings.ReviewProfileConfig{}
517→		}
518→	}
519→	return profiles, nil
520→}
521→
522→func decodeRawReviewDefault(raw map[string]json.RawMessage) string {
523→	if msg, ok := raw["review_default_profile"]; ok && len(msg) > 0 {
524→		var s string
525→		if err := json.Unmarshal(msg, &s); err == nil {
526→			return s
527→		}
528→	}
529→	return ""
530→}
531→
532→func writeRawReviewProfiles(path string, raw map[string]json.RawMessage, profiles map[string]settings.ReviewProfileConfig, defaultName string) error {
533→	profilesJSON, err := json.Marshal(profiles)
534→	if err != nil {
535→		return fmt.Errorf("encode review_profiles: %w", err)
536→	}
537→	raw["review_profiles"] = profilesJSON
538→	if strings.TrimSpace(defaultName) != "" {
539→		defJSON, err := json.Marshal(defaultName)
540→		if err != nil {
541→			return fmt.Errorf("encode review_default_profile: %w", err)
542→		}
543→		raw["review_default_profile"] = defJSON
544→	}
545→	// SaveProjectRaw writes the given path atomically (temp file + rename in the
546→	// same dir) but does not create the directory, so ensure .entire/ exists
547→	// for repos that haven't been enabled yet.
548→	if dir := filepath.Dir(path); dir != "" {
549→		if err := os.MkdirAll(dir, 0o750); err != nil {
550→			return fmt.Errorf("create settings dir %s: %w", dir, err)
551→		}
552→	}
553→	// SaveProjectRaw is path-generic despite the name, so it also serves the
554→	// local settings file.
555→	if err := settings.SaveProjectRaw(path, raw); err != nil {
556→		return fmt.Errorf("write %s: %w", path, err)
557→	}
558→	return nil
559→}
