222→// fakeCellClientBuilder hands out unauthenticated clients keyed by target and
223→// records what it was asked for.
224→type fakeCellClientBuilder struct {
225→	mu      sync.Mutex // fanOutCells calls ClientFor from one goroutine per cell
226→	targets []*auth.CellTarget
227→	err     error
228→}
229→
230→func (f *fakeCellClientBuilder) ClientFor(_ context.Context, target *auth.CellTarget) (*api.Client, error) {
231→	f.mu.Lock()
232→	f.targets = append(f.targets, target)
233→	f.mu.Unlock()
234→	if f.err != nil {
235→		return nil, f.err
236→	}
237→	base := "https://home.api.example"
238→	if target != nil && target.BaseURL != "" {
239→		base = target.BaseURL
240→	}
241→	return api.NewClientWithBaseURL("test-token", base), nil
242→}
