 16→func TestDistinctActiveClusterHosts(t *testing.T) {
 17→	t.Parallel()
 18→	mirrors := []coreapi.Mirror{
 19→		{ClusterHost: "aws-us-east-2.entire.io"},
 20→		{ClusterHost: "AWS-US-EAST-2.entire.io"}, // dup (case-insensitive) → collapses
 21→		{ClusterHost: "aws-eu-west-1.entire.io"}, // distinct active
 22→		// Unique host that is archived → must be excluded (observably absent).
 23→		{ClusterHost: "aws-ap-south-1.entire.io", IsArchived: coreapi.NewOptBool(true)},
 24→		// Unique host with a failed clone → excluded (can't serve experts).
 25→		{ClusterHost: "aws-sa-east-1.entire.io", Status: coreapi.NewOptMirrorStatus(coreapi.MirrorStatusFailed)},
 26→		// Unique host suspended → excluded.
 27→		{ClusterHost: "aws-ca-central-1.entire.io", Status: coreapi.NewOptMirrorStatus(coreapi.MirrorStatusSuspended)},
 28→		{ClusterHost: ""}, // empty → excluded
 29→	}
 30→	got := distinctActiveClusterHosts(mirrors)
 31→	sort.Strings(got)
 32→	want := []string{"aws-eu-west-1.entire.io", "aws-us-east-2.entire.io"}
 33→	if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
 34→		t.Fatalf("distinctActiveClusterHosts = %v, want %v", got, want)
 35→	}
 36→}
